class VduConnection:
    """Provides a python facade for a vDU client. Is meant to be used from python code and thus delivering an OO API"""

    def __init__(self, host, port, username, password, vdu_version=vDuProvider.DEFAULT, secure=False,
                 login_disabled=False, need_all_info=False, timeout=30, use_m2m=False, alias="default",
                 read_only=False, update_expired_password=True, log_dir="", log_level="info"):
        """
        Provides connection and authorization to vDU.

        :param str host: IP address to proper host, f.e. `127.0.0.1`.
        :param str port: Port for connection to vDU.
        :param str username: Username to authenticate to vDU.
        :param str password: Password to authenticate to vDU.
        :param str vdu_version: (optional) SW version of vDU.
                                Available versions:

                                cuoam_19b, cuoam_21b, cuoam_22r2, cuoam_22r4, cuoam_23r1,
                                cuoam_23r2, cuoam_23r3, cuoam_23r4, cuoam_24r1, cuoam_24r2,
                                cuoam_24r3, cuoam_25r1, cuoam_25r2, cuoam_25r3

                                Defaults to the newest implemented release - cuoam_25r3.
        :param bool secure: (optional) If set to True, the connection will be made using HTTPS protocol, otherwise with HTTP,
                            Defaults to False.
        :param bool login_disabled: (optional) If set to True, default token will be used instead log in. Defaults to False.
        :param bool need_all_info: If set to True, all information about the login response will be stored in the connection object,
                                   otherwise, just access token. Defaults to False
        :param int timeout: (optional) Timeout for the operation, default is 30s
        :param bool use_m2m: (optional) If set to true, M2M login(/api/licensed/sec/v1/login) will be used.
                             Otherwise, internal login(/api/sec/v1/login) is used.
                             Defaults to False.
                             Must set use_m2m -> False when login first time after deployment.
        :param str alias: (optional) Name of returned connection. If not provided, this connection becomes "default".
        :param bool read_only: (optional) If set to True, the connection will be read-only. Defaults to False
        :param bool update_expired_password: (optional) If set to True, expired password will be updated
                                             Otherwise the user can use keyword update_expired_password
                                             to change password on their own. Defaults to True.
        :param str log_dir: (optional) directory where log messages from the library will be saved.
                            Name of the file with logs is "vdu_api_debug_{connection_name}.log"
                            When this value is not given logs will be saved in the working directory.
        :param str log_level: (optional) specifies the lowest-severity log message which should be logged to console.
                              Available levels:

                              * debug
                              * info
                              * warning
                              * error
                              * critical

                              Levels are equivalent to python logging module levels,
                              more info can be found here: https://docs.python.org/3/library/logging.html#logging-levels

                              List of available levels is in severity order where "debug" is the lowest severity level
                              and "critical" is the highest severity.
                              If log_level is "info", only INFO, WARNING, ERROR, and CRITICAL messages will be directed
                              to console and DEBUG messages will be ignored.
                              Default value is "info".
        """
        set_log_level(level=log_level)
        direct_logs_to_file(path=log_dir, alias=alias)
        log_library_version()

        self._vdu = vDuProvider.create_vdu(
            host=host,
            port=port,
            username=username,
            password=password,
            vdu_version=vdu_version,
            secure=secure,
            login_disabled=login_disabled,
            need_all_info=need_all_info,
            timeout=timeout,
            use_m2m=use_m2m,
            alias=alias,
            read_only=read_only,
            update_expired_password=update_expired_password
        )

        if login_disabled:
            self._vdu.token_storage.set_default_token(connection_name=self._vdu.con_details.alias)

        else:
            self.login_response = self._vdu.sec.login(
                username=username,
                password=password,
                need_login_info=need_all_info,
                timeout=timeout,
                read_only_mode=read_only
            )

        self.use_m2m = use_m2m
        self.connection_name = alias

    def disconnect(self, timeout=60):
        """
        This method sends logout request
        :param int timeout: (optional) Timeout for the operation. default is 60s
        :return: no return
        """
        self._vdu.sec.logout(timeout=timeout)
        self._vdu.sec.remove_instance(self.connection_name)

    def upload_plan(self, path_to_plan_file, plan_name='default_plan_name', plan_description=None,
                    wait_for_completion=False, timeout=30, **kwargs):
        """
        Adds plan to the "Planned Configuration" section of the staging area

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param str path_to_plan_file: (required) Path to file, which should be uploaded,
                                      like 'C:/../../SCF_vDU_update_trs_668.xml'
        :param str plan_name: (required, only for cuoam_19b) the name given to the plan, for example:'vdu_1_plan'
        :param str plan_description: (optional) The full plan file description.
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
                                         Default is False.
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param bool raw: (optional) If True, return raw response, default is False
        :return: dict with upload plan operation info, for example:
        {
          "raml_parsing_errors": [
            "ramlParseError1",
            "ramlParseError2"
          ],
          "incorrect_objects_feedback": [
            {
              "errorCode": "ParameterWithoutDefinition",
              "path": "MRBTS-1/MNL-1.cmSyncCheckPerio"
            }
            {
              "errorCode": "ObjectNotAllowedToCreate",
              "path:": "MRBTS-10999/NRBTS-1/LTEENB-1"
            }
          ],
          "procedure_state": "planDownload",
          "action_id": 101,
          "links": [
            {
              "rel": "self",
              "herf": "/some/useful/links"
            }
          ],
          "status": "ongoing",
          "error_message": "error message"
        }
        """
        return self._vdu.upload_plan(path_to_plan_file=path_to_plan_file,
                                     plan_name=plan_name,
                                     plan_file_description=plan_description,
                                     wait_for_completion=wait_for_completion,
                                     timeout=timeout,
                                     **kwargs)

