    def create_vdu_object(self, delta_plan_id, parent_mo_dn, mo_name, timeout=30, include_defaults=True):
        """
        online create vdu objects

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param delta_plan_id: the delta plan file id, can be get from - get_delta_plan_info_list
        :param parent_mo_dn: the parent mo distname
        :param mo_name: the mo name you want to create
        :param timeout: (optional) timeout in seconds for request.
        :param bool include_defaults: include default value or not, default value is True.
        :return: create object response including action_id, status
        """
        return self._vdu.create_vdu_object(delta_plan_id=delta_plan_id, parent_mo_dn=parent_mo_dn,
                                           include_defaults=include_defaults, mo_name=mo_name, timeout=timeout)

    def get_create_vdu_object_action_status(self, plan_id, action_id, timeout=30):
        """
        get create vdu object operation stauts

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param plan_id: delta plan id, can be get from - get_delta_plan_info_list
        :param action_id: the create object action id
        :param timeout: (optional) timeout in seconds for request.
        :return: the create object operation status including action_id, status, mo_uuid
        """
        return self._vdu.get_create_vdu_object_action_status(plan_id=plan_id, action_id=action_id, timeout=timeout)

    def update_vdu_parameter(self, plan_id, mo_dn, updated_paras_dict, operation='replace', mo_uuid=None, timeout=30):
        """
        online update vdu parameter. the keyword only can update parameters under one MO. If you want update
        parameters under multi MOes, you need to call the keyword for many times.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param plan_id: delta plan id
        :param mo_dn: the mo distname that contains the parameter like MRBTS-3218/NRBTS-1/NRCELL-1
        :param updated_paras_list: parameters list - ['para_name_1:para_value_1', 'para_name_2:para_value_2', ...],
                                  like ['swResetLevel:0', 'swResetComment:reset by bts']
        :param operation: the operation - add, replace, remove, revert
        :param mo_uuid: (optional) the mo uuid, if not given, the keyword will get the mouuid
        :param timeout: (optional) timeout in seconds for request.
        :return: update parameters response including action_id, status
        """
        return self._vdu.update_vdu_parameter(plan_id=plan_id, mo_dn=mo_dn, updated_paras_dict=updated_paras_dict,
                                              operation=operation, mo_uuid=mo_uuid, timeout=timeout)

