        """
        get the update paras action status.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param plan_id: the delta plan id
        :param action_id: the update parameter action id
        :param timeout: (optional) timeout in seconds for request.
        :return: update parameters response including action_id, status
        """
        return self._vdu.get_update_paras_action_status(plan_id=plan_id, action_id=action_id, timeout=timeout)

