        """
        save delta plan file to local

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param local_path: Local directory to save plan file.
        :param local_filename: Local plan file name
        :return: It returns local plan file path with the plan you want to get.
        """
        path_to_plan = self._vdu.save_delta_plan_file(timeout=timeout)
