    def reset_rmods(self, rmods_list, reset_reason='user', graceful_cell_shutdown=False, wait_for_completion=False, timeout=30, **kwargs):
        """
        Reset Radio Modules with IDs given by rmods_list.

        .. note::
            SUPPORTS INTERNAL AND M2M API

        :param list(str) rmods_list: list of runtime RMOD IDs, for example: ['123', '345']
        :param str reset_reason: the reset reason, default value is 'user'
        :param bool graceful_cell_shutdown: if True cells will be shut gracefully, default value is False
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to complete.
        :param int timeout: timeout in seconds for sending request to OAM
        :param bool raw: (optional) If set to True, the raw response will be returned.
                         Defaults to False.
        :param bool use_m2m: If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        :return: dict including operation_id, status, error_message and detailed statuses for each RMOD, for example:
                            {
                              "id": 101,
                              "links": [
                                {
                                  "rel": "self",
                                  "href": "/some/useful/links"
                                }
                              ],
                              "status": "ongoing",
                              "detailedStatuses": [
                                {
                                  "id": "1",
                                  "status": "failed",
                                  "errorText": "reset is already progressing"
                                },
                                {
                                  "id": "2",
                                  "status": "success"
                                }
                              ],
                              "errorMessage": "error message",
                              "errorCode": {
                                "code": "user_restricted"
                              }
                            }
        """
        return self._vdu.reset_rmods(rmods_list=rmods_list, reset_reason=reset_reason,
                                     graceful_cell_shutdown=graceful_cell_shutdown, wait_for_completion=wait_for_completion, timeout=timeout,
                                     **kwargs)

