    def get_counter_values(self, counter_id, dimension_dn, start_time_lower_limit=None,
                           start_time_upper_limit=None, raw=False):
        """
        Get values of counter with given counter_id and dimension_dn

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param counter_id: the counter id, for example: M55300C00000
        :param dimension_dn: dist name of object that the counter belongs to, for example: MRBTS-5323/NRBTS-5323/NRCELL-1
        :param str start_time_lower_limit: (cuoam_21b only, optional) interval start time coded in percent-encoded
            ISO 8601 format, for example: 2021-03-17T08:11:44+01:00
        :param str start_time_upper_limit: (cuoam_21b only, optional) interval end time coded in percent-encoded
            ISO 8601 format, for example: 2021-03-17T08:11:44+01:00
        :param bool raw: (optional) If True, return raw response, default is False
        :return: a list of dicts containing the counter's start time and value, e.g:
                 [
                  {
                    "startTime" : "2020-10-20T08:00:00+08:00",
                    "value" : "0"
                  },
                  {
                    "startTime" : "2020-10-20T08:15:00+08:00",
                    "value" : "0"
                  }
                 ]
        """
        return self._vdu.get_counter_values(counter_id, dimension_dn,
                                            start_time_lower_limit=start_time_lower_limit,
                                            start_time_upper_limit=start_time_upper_limit, raw=raw)

