    def start_5g_downlink_test(self, nrcell_id, test_model, beam_pattern_id, polarization, power_backoff, ru_mode, phys_cell_id,
                               codebook_2_antports, i11_codebook_4_antports, i2_codebook_4_antports, i13_codebook_4_antports,
                               mimo_rank, p_max, nrarfcn=0, timeout=60, nrarfcn_ul=0, nrarfcn_dl=0, vswr_monitoring=False):
        """
        Executes 5G downlink Test.

        .. important::
            To be able to execute test models it is necessary to fist enter Test Dedicated State by setting
            "swResetLevel" parameter under SWRESETREQ to "resetToTestLevel".

        .. note::
            **API used:**

            * POST /api/cp-config/v1/test-models/operations/downlink/start
            * GET /api/cp-config/v1/test-models/operations/downlink/start/{operationId}
            * DELETE /api/cp-config/v1/test-models/operations/downlink/start/{operationId}

        :param int nrcell_id: configuration ID of cell for which 5G downlink test should be executed, for example: 1.
        :param str test_model: Specifies test model. Available options:

                               * NR-FR1-TM1.1
                               * NR-FR1-TM3.1
                               * NR-FR1-TM3.2
                               * NR-FR1-TM3.1a
                               * NR-FR1-TM1.2
                               * NR-FR1-TM2
                               * NR-FR1-TM2a
                               * NR-FR1-TM3.3

        :param list[Union[int,str]] beam_pattern_id: If the array contains only one element, duplicate and fill the other elements.
                                                     minitems: 4, maxitems: 4, i.e. [ 1, 1, 1, 1 ]
        :param str polarization: Specifies polarization used in test. Available options:

                                 * P_plus45_or_0
                                 * P_minus45_or_90
                                 * P_both

        :param int power_backoff: Specifies power reduction used in test, should be in range: [0, 490]
        :param str ru_mode: Specifies RU mode. Available options:

                            * NR_Only
                            * MSR
                            * Customize_1

        :param int phys_cell_id: Specifies physical cell ID, should be in range: [0, 1007]
        :param Union[int,str] codebook_2_antports: Codebook index for 2x2 MIMO CL Rank1 and Rank2, should be in range: [0, 3]
        :param Union[int,str] i11_codebook_4_antports: Specifies i11Codebook4AntPorts index for 4 layers MIMO, should be in range: [0, 7]
        :param Union[int,str] i2_codebook_4_antports: Specifies i2Codebook4AntPorts index for 4 layers MIMO, should be in range: [0, 3]
                                                      (i2Codebook4AntPorts should be 0 if "polarization" is set to P_plus45_or_0)
        :param Union[int,str] i13_codebook_4_antports: Specifies i13Codebook4AntPorts index for 4 layers MIMO, should be in range: [0, 1]
                                                       (i13_codebook_4_antports should be 0 if mimoRank is set to 1)
        :param str mimo_rank: DL MIMO rank for the testing. Available options:

                              * Rank1
                              * Rank2

        :param Union[int,str] nrarfcn: (optional, mandatory when FR1 TDD) Specifies nrarfcn used in test, should be in range: [0, 3279165]
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 60s
        :param int p_max: (optional) Specifies maximum output power of the cell per TX in test, should be in range: [0, 60]
        :param Union[int,str] nrarfcn_ul: (optional, mandatory when FR1 FDD(uplink)) Specifies nrarfcnUl used in test
        :param Union[int,str] nrarfcn_dl: (optional, mandatory when FR1 FDD(downlink)) Specifies nrarfcnDl used in test
        :param bool vswr_monitoring: (optional) Should VSWR monitoring be triggered during downlink test. Defaults to False

        :raises WrongApiResponseStatus: When NR downlink test fails or if test didn't finish in given timeout.
        :raises TypeError: When parameter beam_pattern_id is not of type list
        :raises ValueError: When parameter beam_pattern_id does not contain 4 elements

        :returns: "success" if no errors occurred
        :rtype: str
        """
        if "NR-FR1-" not in test_model:
            test_model = f"NR-FR1-{test_model}"

        available_test_models = [
            "NR-FR1-TM1.1",
            "NR-FR1-TM3.1",
            "NR-FR1-TM3.2",
            "NR-FR1-TM3.1a",
            "NR-FR1-TM1.2",
            "NR-FR1-TM2",
            "NR-FR1-TM2a",
            "NR-FR1-TM3.3"
        ]

        if test_model not in available_test_models:
            raise ValueError(f"Test Model name you gave: {test_model} is not "
                             f"in the list of available test models: {available_test_models}")

        return self._vdu.start_5g_downlink_test(nrcell_id=nrcell_id,
                                                test_model=test_model,
                                                beam_pattern_id=self._verify_and_prepare_beam_pattern_id(beam_pattern_id),
                                                polarization=polarization,
                                                power_backoff=power_backoff,
                                                p_max=p_max,
                                                nrarfcn=nrarfcn,
                                                ru_mode=ru_mode,
                                                phys_cell_id=phys_cell_id,
                                                codebook_2_antports=codebook_2_antports,
                                                i11_codebook_4_antports=i11_codebook_4_antports,
                                                i2_codebook_4_antports=i2_codebook_4_antports,
                                                i13_codebook_4_antports=i13_codebook_4_antports,
                                                mimo_rank=mimo_rank,
                                                nrarfcn_ul=nrarfcn_ul,
                                                nrarfcn_dl=nrarfcn_dl,
                                                timeout=timeout,
                                                vswr_monitoring=vswr_monitoring)

    @staticmethod
    def _verify_and_prepare_beam_pattern_id(beam_pattern_id):
        if not isinstance(beam_pattern_id, list):
            raise TypeError('Parameter beam_pattern_id should be list type not {}'.format(type(beam_pattern_id)))

        if len(beam_pattern_id) != 4:
            raise ValueError('Parameter beam_pattern_id should contain four elements')

        return [int(element) for element in beam_pattern_id]

    @staticmethod
    def _verify_and_prepare_csi_payload_bit(csi_payload_bit):
        if csi_payload_bit:
            try:
                return [int(element) for element in csi_payload_bit]
            except ValueError:
                raise TypeError(f'Parameter csi_payload_bit should be list type not {type(csi_payload_bit)}')

        else:
            return None

    @staticmethod
    def _verify_digital_output_relations(digital_output_enable, digital_out_type, digital_out_rate, bb_selector):
        if digital_output_enable and digital_out_type == 'SerialRs' and bb_selector is None:
            raise ValueError('Parameter bb_selector should not be None if digital_out_type is SerialRs.')

        if digital_output_enable and (digital_out_type is None or digital_out_rate is None):
            raise ValueError("digital_out_type and digital_out_rate must not be None when "
                             "digital_output_enable is True")

