    def set_ret_configuration(self, target_dn="", timeout=30, **kwargs):
        """
        Set RET configuration

        .. note::
           **API used:**

           +-------------------+------------------------------------------------------------------------+
           | use_m2m           | API Endpoint                                                           |
           +===================+========================================================================+
           | True              | * PATCH /api/licensed/v1/alds/rets/operations/common-configuration     |
           +-------------------+------------------------------------------------------------------------+
           | False             | * PATCH /api/fh/v1/alds/rets/operations/common-configuration           |
           +-------------------+------------------------------------------------------------------------+

        :param str target_dn: distname of the RETU_R. Optional if alias_label argument provided.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) If set to False,
                             internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        :param bool raw: (optional) If True, return raw response, default is False
        :param str device_data: (optional) The RET Configuration File. Should be base64 formatted
        :param str antenna_bearing: (optional) antenna bearing
        :param str max_angle: (optional) max tilt angle position
        :param str mechanical_angle: (optional) mechanical tilt angle
        :param str min_angle: (optional) min tilt angle position
        :param str angle: (optional) antenna angle
        :param str calibration: (optional) the value is true or false
        :param dict antenna_info: (optional) antenna info, for example:

            .. code-block:: python

                {
                    "model_number": "string",
                    "serial_number": "string",
                    "installation_date": "string",
                    "installer_id": "string",
                    "base_station_id": "string",
                    "sector_id": "string"
                }

        :param str alias_label: (optional) A user-defined parameter that uniquely identifies a specific RETU within
                                the same Network Element. If both targetDN and retUAliasLabel are provided,
                                targetDN will be used to identify the RETU and "retUAliasLabel" will be used to update
                                the commissioned RETU with a new label.
        :param bool raw: (optional) If True, return raw response, default is False

        :returns: operation info, for example:

            .. code-block:: python

                {
                  "id": 101,
                  "links": [
                    {
                      "rel": "self",
                      "href": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "detailedStatuses": [
                    {
                      "id": "1",
                      "status": "failed",
                      "errorText": "reset is already progressing"
                    },
                    {
                      "id": "2",
                      "status": "success"
                    }
                  ],
                  "errorMessage": "error message",
                  "errorCode": {
                    "code": "user_restricted"
                  }
                }
        :rtype: dict
        """
        alias_label = kwargs.get("alias_label", "")

        if not alias_label and not target_dn:
            raise ValueError("It is required to provide either 'alias_label' or 'target_dn'")

        return self._vdu.set_ret_configuration(target_dn=target_dn, timeout=timeout, **kwargs)

