    def vdu_get_all_raw_measurement_data(self, timeout=30, target_dir=None, target_file_name=None):
        """
        The keyword is used to collect and return all the stored raw measurement data.

        .. note::
            SUPPORTS M2M API Only

        :param str target_dir: target directory to save pm raw data file.
        :param str target_file_name: target pm raw data file name. It should be passed along with target_dir.
        :param timeout: timeout in seconds for sending request to OAM, default is 30 seconds
        :return str: all of the pm data zip file path
        """
        if target_dir is None and target_file_name is not None:
            raise IncorrectParameterValue("Parameter target_file_name should be passed along with parameter-target_dir")

        tmp_pm_data_file = self._vdu.vdu_get_all_raw_measurement_data(timeout=timeout)

        if target_dir is not None:
            if target_file_name is None:
                target_file_name = os.path.basename(tmp_pm_data_file)
            target_pm_data_path = os.path.join(target_dir, target_file_name)
            copy_file_to_new_location(tmp_pm_data_file, target_pm_data_path)

            return target_pm_data_path
        else:
            return tmp_pm_data_file

