    def activate_l1_iq_data_configuration(self, capture_on_event=False, capture_on_event_from_l1_hi_and_l1_low=False,
                                          dl_nr_subcell_list=None, ul_nr_subcell_list=None, ru_iq_data_parameters_list=None,
                                          capture_frame_offset=None, buffer_cycle=None, reason=None, timeout=30):
        """
        Activate L1 IQ capture configuration.

        .. note::
            SUPPORTS M2M API ONLY

        :param boolean capture_on_event: Flag enabling capture on event mode. Default is False.
        :param boolean capture_on_event_from_l1_hi_and_l1_low: Flag enabling capture on event from L1Hi(RAN NIC) and L1Low(RU). Default is False.
        :param list dl_nr_subcell_list: List of NR dl subcell identifiers. Default is None.
               :param int nrCellId: NR cell instance ID.
               :param int subCellId: NR subcell identifier.
               e.g.
               [{'nrCellId': 0, 'subCellId': 0}]
        :param list ul_nr_subcell_list: List of NR ul subcell identifiers. Default is None.
               :param int nrCellId: NR cell instance ID.
               :param int subCellId: NR subcell identifier.
               e.g.
               [{'nrCellId': 0, 'subCellId': 0}]
        :param list ru_iq_data_parameters_list: RU specific parameters for IQ data capture. If capture_on_event_from_l1_hi_and_l1_low is set to False,
                                                this parameter should not be set. Default is None.
               :param int nrCellId: NR cell instance ID.
               :param str targetRMOD: target RMOD_R distname.
               :param list[dict] arrayElementsPolarization: Array elements in one polarization
                    :param str polarization: Polarization mode from the radio
                    :param list arrayElements: array elements in one polarization on one MADE for mMIMO radio
                    :param str antenna: support antenna for 8t8r radios. Allowed value is ANT1, ANT2, ANT3, ANT4, ANT5, ANT6, ANT7, ANT8
               :param int captureActivityTimer: Capture activity timer in hours
               e.g.
               [{'nrCellId': 0,
                 'targetRMOD': 'MRBTS-10950/EQM_R-1/APEQM_R-1/RMOD_R-1',
                 'arrayElementsPolarization': [{'polarization': 'MINUS_45',
                                                  'arrayElements': [0],
                                                  'antenna': 'ANT1'}],
                 'captureActivityTimer': 1}]
        :param int capture_frame_offset: Capture frame offset. If capture_on_event_from_l1_hi_and_l1_low is set to False, this parameter should
                                         not be set. Default is None.
        :param str buffer_cycle: Buffer cycle. If capture_on_event_from_l1_hi_and_l1_low is set to False, this parameter should not be set.
                                 Allowed value is 2_FRAMES, 4_FRAMES, 8_FRAMES, 16_FRAMES, 32_FRAMES, 64_FRAMES,
                                                  128_FRAMES, 256_FRAMES, 512_FRAMES, 1024_FRAMES.
                                 Default is None.
        :param str reason: Reason of configure L1 IQ Data.
                           Allowed value is NOT_SET, TX_POWER_FAILURE_SLEEPING_CELL, MSG3_FAILURE_SLEEPING_CELL, MSG4_MSG5_FAILURE_SLEEPING_CELL.
                           Default is None.
        :param int timeout: (optional) Timeout for the operation, defaults to 30
        :return str: operation id.
        """

        if not capture_on_event_from_l1_hi_and_l1_low and \
           (buffer_cycle is not None or capture_frame_offset is not None or ru_iq_data_parameters_list is not None):
            raise IncorrectParameterValue("When parameter capture_on_event_from_l1_hi_and_l1_low is set to False, parameters buffer_cycle," \
            " capture_frame_offset and ru_iq_data_parameters_list should not be set.")
        return self._vdu.activate_l1_iq_data_configuration(dl_nr_subcell_list=dl_nr_subcell_list,
                                                           ul_nr_subcell_list=ul_nr_subcell_list,
                                                           ru_iq_data_parameters_list=ru_iq_data_parameters_list,
                                                           capture_frame_offset=capture_frame_offset,
                                                           capture_on_event=capture_on_event,
                                                           capture_on_event_from_l1_hi_and_l1_low=capture_on_event_from_l1_hi_and_l1_low,
                                                           buffer_cycle=buffer_cycle,
                                                           reason=reason,
                                                           timeout=timeout)

