    def add_netconf_accounts(self, accounts_info, authentication_method="deactivation_at_first_connection", timeout=30):
        """
        Add Netconf SSH Accounts to the configuration.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param list accounts_info: list of dictionaries with account info, e.g.
                [
                  {
                    "id": "1",
                    "defaultNetconfAccount": {
                        "defaultNetconfAccountName": "default",
                        "defaultNetconfAccountPwd": "password123"
                  },
                    "additionalNetconfAccount": {
                        "additionalNetconfAccountName": "additional",
                        "additionalNetconfAccountPwd": "paSS!!11",
                        "additionalNetconfAccountType": "sudo"
                  }
                  }
                ]
        "defaultNetconfAccount" is a mandatory key for every account, while "additionalNetconfAccount" is optional.
        Passwords need to be at least 8 characters long and must contain characters from at least two groups below:
            - lower case alphabetic (a - z)
            - uppercase alphabetic (A - Z)
            - numeric (0 - 9)
            - allowed special characters: !$ %^()[]_-~{}.+
        "additionalNetconfAccountPwd" needs to contain at least two characters from each of the groups mentioned above.
        Account names need to be at least 3 characters long and can only consist of lowercase letters and numbers.
        :param str authentication_method: (optional) Authentication method, available options:
            - deactivation_at_first_connection - visible in WebEM as Deactivation of SSH Public Key Validation at
                                                 first connection
            - public_key_based - visible in WebEM as Public Key Based
                                                 Defaults to "deactivation_at_first_connection"
        :param int timeout: (optional) Timeout for the operation, defaults to 30.
        :return: dict with status  and content of response, for example:
                    {
                      "status": "success",
                      "indicationResult": "string",
                      "oruAccountResults": [
                        {
                          "id": "string",
                          "targetDN": "MRBTS-1/EQM-1/APEQM-1/RMOD-1",
                          "resultStatus": "success",
                          "errorCode": "InvalidSshServerFormat",
                          "feedback": "string"
                        }
                      ]
                    }
        """
        return self._vdu.add_netconf_accounts(accounts_info=accounts_info,
                                              authentication_method=authentication_method,
                                              timeout=timeout)

