    def collect_screl(self, directory, coverage='screl', screl_type='local', compressed=False, timeout=600):
        """
        Collect SCREL - System Critical Event Logs

        Perform full SCREL collection operation. Trigger logs collection, wait for completion and download the logs.

        .. note::
            SUPPORTS M2M API ONLY

        :param str directory: absolute directory path where snapshot files will be saved
        :param str coverage: (optional) Type of coverage, allowed value is ['screl', 'screlWithoutPmFm'], defaults to 'screl'.
        :param str screl_type: (optional) Type of screl, allowed value is ['local', 'remote'], defaults to 'local'.
        :param bool compressed (optional): if True, all SCREL files will be compressed into one zip file, defaults to False.
        :param int timeout: (optional) Timeout for the operation, defaults to 600.
        :return str: local path to the downloaded SCREL
                     If SCREL files are compressed, zip file path is returned. i.e. /home/ute/SCREL_20230921163838.zip
                     If SCREL files are not compressed, saving directory path is returned, which is the same as directory parameter.
        """
        return self._vdu.collect_screl(directory=directory, coverage=coverage, screl_type=screl_type, compressed=compressed, timeout=timeout)

