    def get_syslog_info(self, timeout=30):
        """
        Get vDU M2M remote syslog streaming configuration.

        .. important::
            After streaming is stopped, the configuration will be deleted.

        .. note::
            SUPPORTS M2M API ONLY

        :param int timeout: (optional) Timeout for the operation, defaults to 30.
        :raises SyslogConfigurationNotFound: if syslog streaming configuration was not set or was deleted
                                             after streaming was stopped
        :return: dict cointaining syslog streaming configuration, for example:
            {
                "status": "on",
                "startTime": "2017-01-30T00:00:00+00:00",
                "remoteServerAddrs": {
                    "fqdn": "string",
                    "active": "192.168.10.11",
                    "backups": [
                    "192.168.10.12",
                    "192.168.10.13"
                    ]
                },
                "streamParams": {
                    "server": "www.example.com",
                    "port": 6514,
                    "protocol": "TLS",
                    "format": "RFC5424",
                    "dscp": 0,
                    "duration": 1
                }
            }
        """
        try:
            return self._vdu.get_syslog_info(timeout=timeout)
        except ApiException as e:
            raise SyslogConfigurationNotFound(e) if e.status == 404 else e

    def update_syslog_info(self, server, port=5001, protocol='UDP', msg_format='Proprietary', dscp=0, duration=10000, timeout=30):
        """
        Create or update vDU M2M remote syslog streaming configuration.

        .. important::
            After streaming is stopped, the configuration will be deleted.

        .. note::
            SUPPORTS M2M API ONLY

        :param str server: IP address or FQDN of the remote syslog server
        :param int port: (optional) Port number of the remote syslog server, defaults to 5001
        :param str protocol: (optional) Protocol used for the remote syslog server, defaults to 'UDP'
        :param str format: (optional) Format of the syslog messages, defaults to 'Proprietary'
        :param int dscp: (optional) DSCP value for the syslog messages, defaults to 0
        :param int duration: (optional) Duration of the syslog streaming in seconds, defaults to 10000
        :param int timeout: (optional) Timeout for the operation, defaults to 30
        """
        self._vdu.update_syslog_info(server=server, port=port, protocol=protocol, msg_format=msg_format, dscp=dscp,
                                            duration=duration, timeout=timeout)

    def toggle_syslog_streaming(self, start=True, timeout=30):
        """
        Start or stop vDU M2M remote syslog streaming.

        .. important::
            After streaming is stopped, the configuration will be deleted.

        .. note::
            SUPPORTS M2M API ONLY

        :param bool start: (optional) If set to True, the syslog streaming will be started, otherwise it will be stopped.
                           Defaults to True.
        """
        self._vdu.toggle_syslog_streaming(start=start, timeout=timeout)

