    def update_interface_mirroring_configuration(self, usage_state, interface='L1-L2', nr_cell_dns=None, mirroring_time=0,
                                                 timeout=30):
        """
        Update interface mirroring configuration to activate or deactivate mirroring.
        If the usage_state parameter is set to "inactive" all other parameters can be omitted.

        Parallel L1L2 Mirroring option is not available at the moment. If you need to use it,
        please contact the development team.

        .. note::
            SUPPORTS M2M API ONLY

        :param str usage_state: Usage state, use 'active' to activate the mirroring, 'inactive' to deactivate the mirroring.
        :param str interface: (optional) Name of interface to be mirrored, allowed values: 'L1-L2', 'L2Hi-L2Lo'.
                                         Defaults to 'L1-L2'.
        :param list nr_cell_dns: (optional) List of Configuration distnames of NRCELLs. None means all cells.
                                            For example: ['MRBTS-1/NRBTS-1/NRCELL-1', 'MRBTS-1/NRBTS-1/NRCELL-2']
                                            Defaults to None.
        :param int mirroring_time: (optional) The mirroring time duration in seconds.
                                              If set to 0 mirroring will run until stopped manually (by using
                                              update_interface_mirroring_configuration with 'inactive' usage_state).
                                              Defaults to 0.
        :param int timeout: (optional) Timeout for the operation, defaults to 30.

        :raises ApiException: if argument usage_state="inactive" and interface mirroring is already inactive
        :return: dict with updated interface mirroring configuration and information, for example:
        {
            "configuration": {
                "destination": "local",
                "interface": "L1-L2",
                "mirroringTime": 0,
                "nrCellDNs": []
            },
            "mirroringStates": [
                {
                    "nodeId": "0xe21a",
                    "nrCellDNs": [
                        "MRBTS-1/NRBTS-1/NRCELL-1",
                        "MRBTS-1/NRBTS-1/NRCELL-2",
                        "MRBTS-1/NRBTS-1/NRCELL-3",
                        "MRBTS-1/NRBTS-1/NRCELL-4"
                    ],
                    "reason": "ActivatedByOperator",
                    "startTime": "2025-02-05 15:39:44 GMT",
                    "state": "ongoing"
                }
            ],
            "operationStatus": "ongoing",
            "parallelL1L2Mirroring": false,
            "reasoningStatus": "activatedByOperator",
            "usageState": "active"
        }
        """
        return self._vdu.update_interface_mirroring_configuration(usage_state=usage_state,
                                                                  interface=interface,
                                                                  nr_cell_dns=nr_cell_dns,
                                                                  mirroring_time=mirroring_time,
                                                                  timeout=timeout)

