    def start_diagnostic_check(self, allow_service_impact=False, wait_for_completion=False, timeout=300):
        """
        Start diagnostic check. When wait_for_completion is set to False, status of operation can be checked using
        get_diagnostic_check_status keyword.

        .. important::
            vdu_version should be 'cuoam_25r3' as test model is supported in 25R3

        .. note::
            SUPPORTS M2M API ONLY

        :param bool allow_service_impact: (optional) If set to True, then all checkpoints will be executed.
                                          Otherwise, only online checkpoints will be executed. Defaults to False.
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
                                         Defaults to False.
        :param int timeout: (optional) Timeout for the operation, defaults to 300.

        :return: dict with operation_id and status of the operation, for example:

          .. code-block:: python

            {
              "operationId": "1",
              "status": "ongoing",
              "errorMessage": "Failed to run diagnostic check"
            }
        :rtype: dict
        """
        return self._vdu.start_diagnostic_check(allow_service_impact=allow_service_impact,
                                               wait_for_completion=wait_for_completion, timeout=timeout)

