    def start_antenna_monitoring(self, antennas, timeout=30, wait_for_completion=False):
        """
        Start antenna monitoring. When wait_for_completion is set to False, status of operation can be checked using
        get_antenna_monitoring_status keyword.

        .. note::
            **API used:**

           +-------------------------+--------------------------------------------------------------------+
           | wait_for_completion     | API Endpoint                                                       |
           +=========================+====================================================================+
           | False                   | POST /api/licensed/v1/diagnostic/rf-antenna-monitors               |
           +-------------------------+--------------------------------------------------------------------+
           | True                    | POST /api/licensed/v1/diagnostic/rf-antenna-monitors               |
           |                         | GET  /api/licensed/v1/diagnostic/rf-antenna-monitors/{monitor_id}  |
           +-------------------------+--------------------------------------------------------------------+

        :param list antennas: List of dicts of antennas to be monitored. Dicts contain keys "radioRId"
                              and "antlRId". For example:

                              .. code-block:: python

                                 [
                                 {
                                   "radioRId": 1,
                                   "antlRId": 1
                                   },
                                 {
                                   "radioRId": 1,
                                   "antlRId": 2
                                   }
                                 ]
        :param int timeout: (optional) Timeout for the operation, defaults to 30.
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
                                         Defaults to False.
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used.

        :return: dict with monitor_id and status of the operation, for example:

          .. code-block:: python

            {
              "monitorId": 1,
              "status": "ongoing",
              "link": {
                "rel": "self",
                "href": "/api/licensed/v1/diagnostic/rf-antenna-monitors/1"
              }
            }
        :rtype: dict
        """
        if not isinstance(antennas, list):
            raise TypeError(f'Argument antennas should be a list, instead you gave {type(antennas)}')

        for item in antennas:
            if not isinstance(item, dict):
                raise TypeError('Every item in antennas should be a dictionary, '
                                f'instead you provided {item} of type {type(item)}')

        return self._vdu.start_antenna_monitoring(antennas=antennas, timeout=timeout,
                                                  wait_for_completion=wait_for_completion)

