    def trigger_download_of_current_plan(self, include_auto_config_data=True, include_runtime_data=True, timeout=30, use_m2m=True):
        """
        Triggers download of currently activated plan.

        In order to save currently activated plan to local those three steps need to be executed:
            - Step 1: Trigger download of the currently activated plan using trigger_download_of_current_plan
            - Step 2: Check operation status using get_status_of_current_plan_download
            - Step 3: Save the file locally using save_downloaded_plan_to_local

        Alternatively, keywords get_scf and get_current_plan_file combine all the operations from the three separate
        keywords and can be used if there is no need to execute them separately.

        .. note::
            **API used:**

           +-------------------+------------------------------------------------------------------------+
           | use_m2m           | API Endpoints                                                          |
           +===================+========================================================================+
           | True              | * POST /api/licensed/v1/current-plan/operations/uploads                |
           +-------------------+------------------------------------------------------------------------+
           | False             | * POST /api/cm/v2/current-plan/operations/uploads                      |
           +-------------------+------------------------------------------------------------------------+

        :param bool include_auto_config_data: (optional) Whether auto config data should be included in the plan.
                                              Defaults to True.
        :param bool include_runtime_data: (optional) Whether runtime data should be included in the plan.
                                          Defaults to True.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds, defaults to 30
        :param bool use_m2m: (optional) If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults to True.

        :returns: operation info, for example:

            .. code-block:: python

                {
                  "id": "2107a3rf-1ca4-47f5-aff9-c6e2027f173g",
                  "isCompleted": true,
                  "links": [
                    {
                      "rel": "self",
                      "href": "/current-plan/operations/uploads/2107a3rf-1ca4-47f5-aff9-c6e2027f173g"
                    }
                  ]
                }

        :rtype: dict
        """
        return self._vdu.trigger_download_of_current_plan(include_auto_config_data=include_auto_config_data,
                                                          include_runtime_data=include_runtime_data,
                                                          timeout=timeout,
                                                          use_m2m=use_m2m)

    def get_status_of_current_plan_download(self, operation_id, timeout=30, use_m2m=True):
        """
        Returns status of current plan download operation triggered using trigger_download_of_current_plan.
        Operation succeeds when return field "isCompleted" is True.

        In order to save currently activated plan to local those three steps need to be executed:
            - Step 1: Trigger download of the currently activated plan using trigger_download_of_current_plan
            - Step 2: Check operation status using get_status_of_current_plan_download
            - Step 3: Save the file locally using save_downloaded_plan_to_local

        Alternatively, keywords get_scf and get_current_plan_file combine all the operations from the three separate
        keywords and can be used if there is no need to execute them separately.

        .. note::
            **API used:**

           +-------------------+-------------------------------------------------------------------------+
           | use_m2m           | API Endpoints                                                           |
           +===================+=========================================================================+
           | True              | * GET /api/licensed/v1/current-plan/operations/uploads/{operationId}    |
           +-------------------+-------------------------------------------------------------------------+
           | False             | * GET /api/cm/v2/current-plan/operations/uploads/{operationId}          |
           +-------------------+-------------------------------------------------------------------------+

        :param str operation_id: ID of upload operation, "id" field of trigger_current_plan_upload return
        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds, defaults to 30
        :param bool use_m2m: (optional) If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults to True.

        .. code-block:: python

                {
                  "id": "2107a3rf-1ca4-47f5-aff9-c6e2027f173g",
                  "isCompleted": true,
                  "links": [
                    {
                      "rel": "self",
                      "href": "/current-plan/operations/uploads/2107a3rf-1ca4-47f5-aff9-c6e2027f173g"
                    }
                  ]
                }

        :rtype: dict
        """
        return self._vdu.get_status_of_current_plan_download(operation_id=operation_id, timeout=timeout, use_m2m=use_m2m)

    def save_downloaded_plan_to_local(self, operation_id, path, timeout=30, use_m2m=True):
        """
        Save current plan downloaded using trigger_download_of_current_plan to the local directory given by path.

        In order to save currently activated plan to local those three steps need to be executed:
            - Step 1: Trigger download of the currently activated plan using trigger_download_of_current_plan
            - Step 2: Check operation status using get_status_of_current_plan_download
            - Step 3: Save the file locally using save_downloaded_plan_to_local

        Alternatively, keywords get_scf and get_current_plan_file combine all the operations from the three separate
        keywords and can be used if there is no need to execute them separately.

        .. note::
            **API used:**

           +-------------------+------------------------------------------------------------------------------+
           | use_m2m           | API Endpoints                                                                |
           +===================+==============================================================================+
           | True              | * GET /api/licensed/v1/current-plan/operations/uploads/{operationId}/file    |
           +-------------------+------------------------------------------------------------------------------+
           | False             | * GET /api/cm/v2/current-plan/operations/uploads/{operationId}/file          |
           +-------------------+------------------------------------------------------------------------------+

        :param str operation_id: ID of upload operation, "id" field of trigger_current_plan_upload or
                                 get_status_of_current_plan_upload return
        :param str path: path where current plan should be saved, along with the name of the file,
                         for example: "/home/ute/Desktop/current_plan.xml"
        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds, defaults to 30
        :param bool use_m2m: (optional) If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        """
        self._vdu.save_downloaded_plan_to_local(operation_id=operation_id, path=path, timeout=timeout, use_m2m=use_m2m)

    def update_tx_power_thresholds(self, thresholds):
        """
        Update TX power thresholds - equivalent of "VSWR Tx Power Level Threshold Configuration section" of Test Model
        preparation in WebEM.

        :param list(dict) thresholds: list of dictionaries containing "antlRDN" - Antenna Line Runtime Distname and
                                      "vswrAlarmTxPwrThreshold" - threshold value for this antenna line in dBm.
                                      For example:

                                      .. code-block:: python

                                        [
                                          {
                                            "antlRDN": "MRBTS-11077/EQM_R-1/APEQM_R-1/RMOD_R-1/ANTL_R-1",
                                            "vswrAlarmTxPwrThreshold": 29
                                          },
                                          {
                                            "antlRDN": "MRBTS-11077/EQM_R-1/APEQM_R-1/RMOD_R-1/ANTL_R-2",
                                            "vswrAlarmTxPwrThreshold": 27
                                          },
                                          {
                                            "antlRDN": "MRBTS-11077/EQM_R-1/APEQM_R-1/RMOD_R-3/ANTL_R-1",
                                            "vswrAlarmTxPwrThreshold": 50
                                          },
                                          {
                                            "antlRDN": "MRBTS-11077/EQM_R-1/APEQM_R-1/RMOD_R-3/ANTL_R-3",
                                            "vswrAlarmTxPwrThreshold": 32
                                          }
                                        ]

        :raises TypeError: when thresholds is not a list of dictionaries
        :raises ValueError: when one of the thresholds dictionaries does not contain both
                            "antlRDN" and "vswrAlarmTxPwrThreshold" keys

        :returns: operation info, for example:

            .. code-block:: python

                {
                  "operationId": "1",
                  "status": "ongoing",
                  "link": {
                    "rel": "self",
                    "href": "/api/fh/v1/diagnostic/operations/thresholds/tx-power/1"
                  }
                }
        :rtype: dict
        """
        if not isinstance(thresholds, list):
            raise TypeError(f"Thresholds argument has to be a list of dictionaries not {type(thresholds)}")

        for threshold in thresholds:
            if not isinstance(threshold, dict):
                raise TypeError(f"Thresholds argument has to be a list of dictionaries not {type(threshold)}")

            if "antlRDN" not in threshold.keys() or "vswrAlarmTxPwrThreshold" not in threshold.keys():
                raise ValueError("Each of the thresholds dictionaries has to contain both "
                                 f"'antlRDN' and 'vswrAlarmTxPwrThreshold' keys, you gave {list(threshold.keys())}")

        return self._vdu.update_tx_power_thresholds(thresholds=thresholds)

